#ifndef CG3_INTERSECTIONS2_H
#define CG3_INTERSECTIONS2_H

#include <cg3/utilities/const.h>
#include "segment2.h"

namespace cg3 {
namespace internal {

static Point2d point2DDummy;

} //namespace cg3::internal

bool checkSegmentIntersection2(
        const Segment2d& seg1,
        const Segment2d& seg2,
        const bool ignoreEndPoints);

void checkSegmentIntersection2(
        const Segment2d& seg1,
        const Segment2d& seg2,
        char& code,
        const double eps = cg3::CG3_EPSILON,
        Point2d& intersectionPoint = internal::point2DDummy);

} //namespace cg3

#ifndef CG3_STATIC
#define CG3_INTERSECTIONS2_CPP "intersections2.cpp"
#include CG3_INTERSECTIONS2_CPP
#undef CG3_INTERSECTIONS2_CPP
#endif

#endif // CG3_INTERSECTIONS2_H

/*
 * This file is part of cg3lib: https://github.com/cg3hci/cg3lib
 * This Source Code Form is subject to the terms of the GNU GPL 3.0
 *
 * @author Stefano Nuvoli (stefano.nuvoli@gmail.com)
 */

#include "intersections2.h"

#include <cg3/utilities/utils.h>

namespace cg3 {

/* ----- INTERNAL FUNCTION DECLARATION ----- */

namespace internal {

bool areCollinearPoints(
        const Point2d& a,
        const Point2d& b,
        const Point2d& c,
        const double eps);

bool isBetween(
        const Point2d& a,
        const Point2d& b,
        const Point2d& c,
        const double eps);
} //namespace cg3::internal


/* ----- IMPLEMENTATION OF INTERSECTION CHECK ----- */

/**
 * @ingroup cg3core
 * @brief Check if two segments have an intersection
 * @param[in] seg1 Segment 1
 * @param[in] seg2 Segment 2
 * @param[in] ignoreEndPoints Ignore if endpoints are the same
 * @return True if segments have an intersection
 */
CG3_INLINE bool checkSegmentIntersection2(
        const Segment2d& seg1,
        const Segment2d& seg2,
        const bool ignoreEndPoints)
{
    char code;

    cg3::checkSegmentIntersection2(seg1, seg2, code);

    //Intersection found
    if (code == '1')
        return true;

    //Common endpoint (v) or common endpoint and equals(s)
    if (!ignoreEndPoints && (code == 'v' || code == 's' || code == 'e'))
        return true;

    return false;
}


/**
 * @ingroup cg3core
 * @brief Check if two segments have an intersection
 * @param[in] seg1 Segment 1
 * @param[in] seg2 Segment 2
 * @param[out] code Character identifying the result
 * @param[in] eps Epsilon for operations
 * @param[out] intersectionPoint Point in which the segment intersect
 */
CG3_INLINE void checkSegmentIntersection2(
        const Segment2d& seg1,
        const Segment2d& seg2,
        char& code,
        const double eps,
        Point2d& intersectionPoint)
{
    /* Return char characterizing intersection.
     *
     * 'e': The segments collinearly overlap, sharing a point.
     * 'v': An endpoint (vertex) of one segment is on the other segment,
     *      but 'e' doesn't hold.
     * '1': The segments intersect properly (i.e., they share a point and
     *      neither 'v' nor 'e' holds).
     * 's': The segments are the same.
     * '0': The segments do not intersect (i.e., they share no points).
     *
     */
    code = '?';

    double  s, t;       /* The two parameters of the parametric eqns. */
    double num, denom;  /* Numerator and denoninator of equations. */

    Point2d a = seg1.p1();
    Point2d b = seg1.p2();
    Point2d c = seg2.p1();
    Point2d d = seg2.p2();

    //Same segment
    if ((cg3::epsilonEqual(a, c, eps) && cg3::epsilonEqual(b, d, eps)) ||
        (cg3::epsilonEqual(a, d, eps) && cg3::epsilonEqual(b, c, eps)))
    {
        intersectionPoint = a;
        code = 's';
        return;
    }

    //Endpoints
    if (cg3::epsilonEqual(a, c, eps) || cg3::epsilonEqual(a, d, eps)) {
        intersectionPoint = a;
        code = 'v';
        return;
    }
    else if (cg3::epsilonEqual(b, d, eps) || cg3::epsilonEqual(c, b, eps))
    {
        intersectionPoint = b;
        code = 'v';
        return;
    }

    denom =
            a.x() * ( d.y() - c.y() ) +
            b.x() * ( c.y() - d.y() ) +
            d.x() * ( b.y() - a.y() ) +
            c.x() * ( a.y() - b.y() );

    // If denom is zero, then segments are parallel: handle separately.
    if (cg3::epsilonEqual(denom, 0.0, eps)) {
        if (internal::areCollinearPoints(a, b, c, eps)) { //Collinear points
            if (internal::isBetween(a, b, c, eps)) {
                intersectionPoint = c; //Set intersection point
                code = 'e';
            }
            else if (internal::isBetween(a, b, d,eps)) {
                intersectionPoint = d; //Set intersection point
                code = 'e';
            }
            else if (internal::isBetween(c, d, a, eps)) {
                intersectionPoint = a; //Set intersection point
                code = 'e';
            }
            else if (internal::isBetween(c, d, b, eps)) {
                intersectionPoint = b; //Set intersection point
                code = 'e';
            }
            else {
                code = '0';
            }
        }
        else {
            code = '0';
        }
    }
    else {
        num =
                a.x() * ( d.y() - c.y() ) +
                c.x() * ( a.y() - d.y() ) +
                d.x() * ( c.y() - a.y() );


        s = num / denom;


        num =
                -(a.x() * ( c.y() - b.y() ) +
                  b.x() * ( a.y() - c.y() ) +
                  c.x() * ( b.y() - a.y() ) );


        t = num / denom;


        //Intersection found
        if ((0.0 <= s) && (s <= 1.0) && (0.0 <= t) && (t <= 1.0)) {
            code = '1';

